function journeyFingerprint(sessions){const source=JSON.stringify(sessions.map(s=>[s.id,s.date,s.count,s.seconds,s.mode]));let hash=2166136261;for(let i=0;i<source.length;i++){hash^=source.charCodeAt(i);hash=Math.imul(hash,16777619)}return(hash>>>0).toString(16)}
function journeySnapshot(journey=null){const sessions=[...(journey?.sessions||data.sessions)].sort((a,b)=>new Date(a.date)-new Date(b.date));return{sessions,total:sessions.reduce((n,s)=>n+Number(s.count),0),name:journey?.name||data.profile?.name||'',generatedAt:new Date().toISOString(),isArchive:!!journey,fingerprint:journeyFingerprint(sessions)}}
function selectedJourney(){const id=$('#journey-history-select')?.value;return(data.journeys||[]).find(j=>j.id===id)||null}
function canStartNewJourney(){const receipt=data.recognitionReceipt;return total()>=1000000&&!!receipt?.confirmed&&receipt.fingerprint===journeySnapshot().fingerprint&&!running&&!elapsed}
function refreshMilestone(){const key=[total(),data.sessions.length,data.recognitionReceipt?.fingerprint||'',data.recognitionReceipt?.confirmedAt||'',running,elapsed>0].join('|');if(refreshMilestone.last===key)return;refreshMilestone.last=key;const eligible=canStartNewJourney(),done=total()>=1000000;$('#reset-journey').disabled=!eligible;$('#milestone-recognition').classList.toggle('hidden',!done);$('#milestone-copy').textContent=!done?'Al llegar al millón, guarda tu reconocimiento para comenzar otro recorrido.':running||elapsed?'Guarda o descarta la sesión en curso antes de iniciar otro recorrido.':eligible?'Tu reconocimiento está guardado. Puedes abrir un nuevo camino; este quedará archivado.':'¡Completaste el millón! Descarga tu reconocimiento y confirma que lo guardaste para comenzar otro recorrido.'}
function csvForJourney(snapshot){const lines=[['Fecha','Hora','Daimoku','Duración_segundos','Modo','Acumulado']];let cumulative=0;for(const session of snapshot.sessions){cumulative+=session.count;const date=new Date(session.date);lines.push([date.toLocaleDateString('es-CL'),date.toLocaleTimeString('es-CL',{hour12:false}),session.count,Math.round(session.seconds),{listen:'Estimación con voz',timer:'Estimación por tiempo',manual:'Registro manual'}[session.mode]||session.mode,cumulative])}return'\uFEFF'+lines.map(row=>row.map(value=>'"'+String(value).replaceAll('"','""')+'"').join(';')).join('\r\n')}
function downloadFile(content,type,name){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function reportDate(value,short=false){return new Date(value).toLocaleDateString('es-CL',short?{day:'2-digit',month:'2-digit',year:'numeric'}:{day:'numeric',month:'long',year:'numeric'})}
function reportFormat(value){return Math.floor(value).toLocaleString('es-CL')}
