 const rect=(x,y,w,h,color)=>{doc.setFillColor(...color);doc.rect(x,y,w,h,'F')};
 function pageBase(){pages++;rect(0,0,210,297,[250,251,248]);rect(17,17,58,.9,blue);rect(75,17,58,.9,[209,219,225]);rect(133,17,60,.9,red);txt('daimoku chile',18,31,13,ink,'bold');txt('CADA DAIMOKU CUENTA',192,31,7,muted,'normal',{align:'right'});doc.setDrawColor(214,224,229);doc.setLineWidth(.25);doc.line(18,279,192,279);txt('Una práctica personal. Un horizonte compartido.',18,285,7,muted);txt(String(pages),192,285,7,muted,'normal',{align:'right'})}
 function geographicMap(x,y,height){const scale=height/630,ops=[];const outline=CHILE_MAP.path.split('M').filter(Boolean).filter(r=>parseFloat(r.split(',')[0])>=95).map(r=>'M'+r).join(' ');const parts=outline.match(/[MLZ]|-?\d+(?:\.\d+)?/g)||[];let at=0;while(at<parts.length){const type=parts[at++];if(type==='Z')ops.push({op:'h',c:[]});else{const px=Number(parts[at++]),py=Number(parts[at++]);ops.push({op:type==='M'?'m':'l',c:[x+(px-95)*scale,y+(py-20)*scale]})}}doc.setFillColor(228,236,240);doc.path(ops);doc.fill();const completed=Math.min(1000,Math.floor(snapshot.total/1000));CHILE_MAP.cells.slice(0,completed).forEach(([px,py],i)=>{if(px<95)return;const hex=MAP_TILE_COLORS[i],rgb=[1,3,5].map(a=>parseInt(hex.slice(a,a+2),16));rect(x+(px-95)*scale,y+(py-20)*scale,CHILE_MAP.step*scale,CHILE_MAP.step*scale,rgb)});doc.setDrawColor(47,88,118);doc.setLineWidth(.18);doc.path(ops);doc.stroke()}
 const dates=snapshot.sessions.map(s=>new Date(s.date).toLocaleDateString('en-CA'));const days=new Set(dates).size,period=snapshot.sessions.length?`${reportDate(snapshot.sessions[0].date)} al ${reportDate(snapshot.sessions.at(-1).date)}`:'Sin sesiones guardadas';
 if(recognition){pageBase();txt('RECONOCIMIENTO PERSONAL',18,51,9,blue,'bold');txt('Cada daimoku',18,73,32,ink,'bold');txt('cuenta.',18,88,32,red,'bold');txt('Este recorrido pertenece a',18,107,11,muted);doc.setFont('helvetica','bold');doc.setFontSize(24);const identity=doc.splitTextToSize(name.trim()||'Tu propio camino',126).slice(0,2);txt(identity,18,123,24,ink,'bold');paragraph(snapshot.total>=1000000?'Por completar un millón de daimoku y cultivar, paso a paso, un camino de dedicación y constancia.':'Por dar un lugar a tu intención y cultivar, paso a paso, un camino de dedicación y constancia.',18,151,124,11,muted);txt(reportFormat(snapshot.total),18,187,33,blue,'bold');txt('DAIMOKU REGISTRADOS',19,197,9,muted);txt(`${snapshot.sessions.length} sesiones`,18,216,12,ink,'bold');txt(`${days} ${days===1?"día":"días"} con práctica`,76,216,12,ink,'bold');const progress=Math.min(1,snapshot.total/1000000);rect(18,228,124,2,[218,228,233]);if(progress)rect(18,228,124*progress,2,red);txt(`${Math.min(1000,Math.floor(snapshot.total/1000))} de 1.000 cuadros - ${(progress*100).toLocaleString('es-CL',{maximumFractionDigits:2})}% del viaje`,18,239,9,muted);paragraph('Recorrido: '+period,18,251,170,9,muted);txt('Generado el '+reportDate(snapshot.generatedAt),18,267,8,muted);geographicMap(148,59,184);txt('Reconocimiento personal, sin afiliación ni aval de SGI.',18,275,7,muted);doc.addPage()}
