async function saveJourneyPDF(snapshot,recognition=false,name=snapshot.name){const doc=buildJourneyPDF(snapshot,{recognition,name});await doc.save(`${recognition?'reconocimiento':'bitacora'}-daimoku-chile-${localDay(Date.now())}.pdf`,{returnPromise:true});return doc}
function showExportOptions(){const snapshot=journeySnapshot(selectedJourney());modal(`<h2>Tu camino, para conservar.</h2><p>${fmt(snapshot.total)} daimoku en ${snapshot.sessions.length} sesiones${snapshot.isArchive?' de un recorrido archivado':''}. Elige cómo llevarlos contigo.</p><div class="export-choices"><button class="secondary" id="csv-download"><b>Excel y hojas de cálculo</b><small>Archivo CSV con cada sesión y su acumulado.</small></button><button class="secondary" id="pdf-download"><b>Bitácora en PDF</b><small>Un documento legible para guardar o imprimir.</small></button><button class="secondary" id="json-download"><b>Respaldo técnico en JSON</b><small>Datos completos, incluidos los recorridos archivados.</small></button></div>`);$('#csv-download').onclick=()=>{downloadFile(csvForJourney(snapshot),'text/csv;charset=utf-8','bitacora-daimoku-chile.csv');toast('Se solicitó la descarga de tu CSV')};$('#json-download').onclick=()=>downloadFile(JSON.stringify({app:'Daimoku Chile',schemaVersion:1,exportedAt:new Date().toISOString(),...data},null,2),'application/json','respaldo-daimoku-chile.json');$('#pdf-download').onclick=async()=>{try{await saveJourneyPDF(snapshot);toast('Se solicitó la descarga de tu bitácora PDF')}catch(e){toast(e.message)}}}
function showRecognition(journey=selectedJourney()){const snapshot=journeySnapshot(journey);if(!snapshot.sessions.length)return toast('Guarda tu primera sesión para generar un reconocimiento.');modal(`<h2>Cada paso merece un lugar.</h2><p>Tu reconocimiento incluirá ${fmt(snapshot.total)} daimoku, el mapa de tu avance y la bitácora completa. Es personal y no constituye una certificación oficial.</p><label for="recognition-name">Tu nombre o seudónimo (opcional)</label><input id="recognition-name" maxlength="60" value="${esc(snapshot.name)}" placeholder="Como quieres aparecer en tu reconocimiento"><button class="primary" id="recognition-download">Descargar reconocimiento PDF</button><div id="recognition-confirm" class="hidden"><p>Revisa la descarga. Cuando tu PDF esté guardado, confírmalo para habilitar un nuevo recorrido.</p><button class="secondary" id="recognition-saved">Ya guardé mi reconocimiento</button></div>`);$('#recognition-download').onclick=async()=>{const name=$('#recognition-name').value.trim();try{await saveJourneyPDF(snapshot,true,name);if(!journey){data.profile={...(data.profile||{}),name};persist()}if(!journey&&snapshot.total>=1000000&&snapshot.fingerprint===journeySnapshot().fingerprint){$('#recognition-confirm').classList.remove('hidden');$('#recognition-saved').onclick=()=>{if(snapshot.fingerprint!==journeySnapshot().fingerprint)return toast('El recorrido cambió. Genera un reconocimiento actualizado.');data.recognitionReceipt={fingerprint:snapshot.fingerprint,total:snapshot.total,confirmed:true,confirmedAt:new Date().toISOString()};persist();refreshMilestone();$('#modal').close();toast('Reconocimiento confirmado. Tu próximo recorrido está disponible.')}}else toast('Se solicitó la descarga de tu reconocimiento PDF')}catch(e){toast(e.message)}}}
function startNewJourney(){if(!canStartNewJourney())return toast('Completa el millón y guarda su reconocimiento antes de reiniciar.');modal(`<h2>Un nuevo horizonte.</h2><p>Se archivarán tus ${fmt(total())} daimoku y sus sesiones. El nuevo mapa comenzará en cero. Tus intenciones y tu ritmo se conservarán; podrás volver a descargar el reconocimiento anterior desde la bitácora.</p><button class="primary" id="confirm-new-journey">Archivar y comenzar de nuevo</button><button class="text-button" id="cancel-new-journey">Seguir con este recorrido</button>`);$('#cancel-new-journey').onclick=()=>$('#modal').close();$('#confirm-new-journey').onclick=()=>{if(!canStartNewJourney())return toast('El recorrido cambió. Revisa el reconocimiento antes de continuar.');const snapshot=journeySnapshot();const archive={id:crypto.randomUUID(),name:snapshot.name,sessions:data.sessions.map(s=>({...s})),completedAt:new Date().toISOString(),recognitionReceipt:{...data.recognitionReceipt}};const next={...data,sessions:[],journeys:[...(data.journeys||[]),archive],recognitionReceipt:null};try{localStorage.setItem(KEY,JSON.stringify(next))}catch{return toast('No se pudo archivar por falta de espacio. El recorrido no se reinició.')}data=next;$('#journey-history-select').value='';mapCamera.mode='follow';render();$('#modal').close();location.hash='inicio';toast('Nuevo recorrido iniciado. El anterior quedó archivado.')}}
function renderJourneyHistory(){const selector=$('#journey-history-select'),previous=selector.value;selector.innerHTML='<option value="">Mi recorrido actual</option>'+(data.journeys||[]).map((j,i)=>`<option value="${j.id}">Recorrido ${i+1} - ${reportDate(j.completedAt,true)} - ${fmt(j.sessions.reduce((n,s)=>n+s.count,0))} daimoku</option>`).join('');selector.value=(data.journeys||[]).some(j=>j.id===previous)?previous:'';const archive=selectedJourney(),snapshot=journeySnapshot(archive);$('#history-summary').textContent=archive?'Recorrido archivado. Sus registros se conservan completos.':`${snapshot.sessions.length} sesiones guardadas - ${fmt(snapshot.total)} daimoku en este recorrido.`;
 $('#history').innerHTML=snapshot.sessions.length?[...snapshot.sessions].reverse().map(s=>`<article class="record"><div><strong>${reportDate(s.date)}</strong><p>${{listen:'Estimación con voz',timer:'Estimación por tiempo',manual:'Registro manual'}[s.mode]||'Registro'} · ${Math.floor(s.seconds/60)} min ${Math.floor(s.seconds%60)} s</p></div><strong>${fmt(s.count)} daimoku</strong>${archive?'':`<button class="delete" data-session="${s.id}" aria-label="Eliminar sesión">×</button>`}</article>`).join(''):'<div class="empty"><span>▤</span>Tu camino comienza con la primera sesión.<br>Lo que cultives hoy aparecerá aquí.</div>';
 $$('[data-session]').forEach(b=>b.onclick=()=>{modal('<h2>Eliminar esta sesión</h2><p>Esta sesión dejará de sumar al mapa y a tu bitácora.</p><button class="primary" id="confirm-delete">Eliminar sesión</button>');$('#confirm-delete').onclick=()=>{data.sessions=data.sessions.filter(s=>s.id!==b.dataset.session);persist();render();$('#modal').close();toast('Sesión eliminada')}});selector.onchange=renderJourneyHistory;
}
function initJourneyExports(){$('#export').onclick=showExportOptions;$('#recognition').onclick=()=>showRecognition();$('#milestone-recognition').onclick=()=>showRecognition(null);$('#reset-journey').onclick=startNewJourney;initBackupImport()}
const IMPORT_MAX_BYTES=8*1024*1024,IMPORT_MAX_SESSIONS=50000,IMPORT_MAX_INTENTIONS=10000,IMPORT_MAX_JOURNEYS=200;
function importText(value,max){return typeof value==='string'?value.trim().slice(0,max):''}
function importDate(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toISOString():null}
function importId(value){const id=typeof value==='string'?value.trim().slice(0,120):'';return /^[A-Za-z0-9_-]+$/.test(id)?id:crypto.randomUUID()}
function importSession(value){if(!value||typeof value!=='object')return null;const count=Number(value.count),seconds=Number(value.seconds),date=importDate(value.date);if(!Number.isInteger(count)||count<1||count>10000000||!Number.isFinite(seconds)||seconds<0||seconds>315360000||!date)return null;const session={id:importId(value.id),date,count,seconds,mode:['listen','timer','manual'].includes(value.mode)?value.mode:'manual'};const rate=Number(value.rate);if(Number.isFinite(rate)&&rate>=1&&rate<=300)session.rate=rate;return session}
function importSessions(value){const raw=Array.isArray(value)?value:[],sessions=[],seen=new Set();let invalid=Math.max(0,raw.length-IMPORT_MAX_SESSIONS);raw.slice(0,IMPORT_MAX_SESSIONS).forEach(item=>{const session=importSession(item);if(!session||seen.has(session.id)){invalid++;return}seen.add(session.id);sessions.push(session)});sessions.sort((a,b)=>new Date(a.date)-new Date(b.date));return{sessions,invalid}}
function importIntention(value){if(!value||typeof value!=='object')return null;const text=importText(value.text,300);if(!text)return null;return{id:importId(value.id),text,done:!!value.done}}
function importJourney(value){if(!value||typeof value!=='object')return null;const sessions=importSessions(value.sessions);if(!sessions.sessions.length)return null;return{id:importId(value.id),name:importText(value.name,60),sessions:sessions.sessions,completedAt:importDate(value.completedAt)||new Date().toISOString()}}
function importReceipt(value,sessions){if(!value||typeof value!=='object'||value.confirmed!==true)return null;const fingerprint=journeyFingerprint(sessions);if(value.fingerprint!==fingerprint)return null;const total=Number(value.total);if(!Number.isFinite(total))return null;return{fingerprint,total,confirmed:true,confirmedAt:importDate(value.confirmedAt)||new Date().toISOString()}}
function parseBackup(text){let parsed;try{parsed=JSON.parse(text)}catch{throw new Error('El archivo no es un JSON válido.')}const source=parsed&&typeof parsed==='object'&&parsed.data&&typeof parsed.data==='object'?parsed.data:parsed;if(!source||typeof source!=='object'||(!Array.isArray(source.sessions)&&!Array.isArray(source.intentions)&&!Array.isArray(source.journeys)))throw new Error('El archivo no parece un respaldo de Daimoku Chile.');const sessionResult=importSessions(source.sessions),intentions=[],seenIntentions=new Set(),rawIntentions=Array.isArray(source.intentions)?source.intentions:[];let invalid=sessionResult.invalid+Math.max(0,rawIntentions.length-IMPORT_MAX_INTENTIONS);rawIntentions.slice(0,IMPORT_MAX_INTENTIONS).forEach(value=>{const intention=importIntention(value);if(!intention||seenIntentions.has(intention.id)){invalid++;return}seenIntentions.add(intention.id);intentions.push(intention)});const journeys=[],seenJourneys=new Set(),rawJourneys=Array.isArray(source.journeys)?source.journeys:[];invalid+=Math.max(0,rawJourneys.length-IMPORT_MAX_JOURNEYS);rawJourneys.slice(0,IMPORT_MAX_JOURNEYS).forEach(value=>{const journey=importJourney(value);if(!journey||seenJourneys.has(journey.id)){invalid++;return}seenJourneys.add(journey.id);journeys.push(journey)});const rate=Number(source.rate),threshold=Number(source.threshold);return{sessions:sessionResult.sessions,intentions,journeys,rate:Number.isFinite(rate)&&rate>=0&&rate<=300?rate:0,threshold:Number.isFinite(threshold)&&threshold>0&&threshold<=1?threshold:.025,profile:source.profile&&typeof source.profile.name==='string'?{name:importText(source.profile.name,60)}:null,recognitionReceipt:importReceipt(source.recognitionReceipt,sessionResult.sessions),invalid}}
function openBackupImport(){if(running||elapsed)return toast('Guarda o descarta la sesión en curso antes de importar.');const input=$('#import-file');if(!input)return;input.value='';input.click()}
async function readBackupFile(file){if(!file)return;if(file.size>IMPORT_MAX_BYTES)return toast('El archivo supera el límite de 8 MB.');try{showImportPreview(parseBackup(await file.text()),file.name)}catch(error){toast(error.message||'No se pudo leer el respaldo.')}}
function showImportPreview(backup,fileName){const importedTotal=backup.sessions.reduce((n,s)=>n+s.count,0),days=new Set(backup.sessions.map(s=>localDay(s.date))).size,sessionLabel=backup.sessions.length===1?'sesión':'sesiones',intentionLabel=backup.intentions.length===1?'intención':'intenciones',journeyLabel=backup.journeys.length===1?'recorrido archivado':'recorridos archivados',invalidLabel=backup.invalid===1?'registro inválido':'registros inválidos',invalidVerb=backup.invalid===1?'será omitido':'serán omitidos';modal(`<h2>Restaurar un respaldo.</h2><p><b>${esc(fileName)}</b></p><p>${fmt(backup.sessions.length)} ${sessionLabel} · ${fmt(importedTotal)} daimoku · ${days} ${days===1?'día':'días'} con práctica.</p><p>${fmt(backup.intentions.length)} ${intentionLabel} · ${backup.journeys.length} ${journeyLabel}.</p>${backup.invalid?`<p>${fmt(backup.invalid)} ${invalidLabel} ${invalidVerb}.</p>`:''}<p>Fusionar conserva tus datos actuales y añade lo que falte. Reemplazar sustituye todo; antes se descargará una copia de seguridad de tus datos actuales.</p><button class="primary" id="import-merge">Fusionar con mis datos</button><button class="secondary" id="import-replace">Reemplazar mis datos</button><button class="text-button" id="import-cancel">Cancelar</button>`);$('#import-merge').onclick=()=>mergeBackup(backup);$('#import-replace').onclick=()=>confirmBackupReplace(backup);$('#import-cancel').onclick=()=>$('#modal').close()}
function mergeRecords(current,incoming){const seen=new Set(current.map(item=>item.id)),merged=[...current];incoming.forEach(item=>{if(!seen.has(item.id)){seen.add(item.id);merged.push(item)}});return merged}
function mergeBackup(backup){const next={...data,sessions:mergeRecords(data.sessions||[],backup.sessions),intentions:mergeRecords(data.intentions||[],backup.intentions),journeys:mergeRecords(data.journeys||[],backup.journeys)};next.sessions.sort((a,b)=>new Date(a.date)-new Date(b.date));if(!next.rate&&backup.rate)next.rate=backup.rate;if(!next.profile?.name&&backup.profile?.name)next.profile=backup.profile;if(!next.recognitionReceipt&&backup.recognitionReceipt)next.recognitionReceipt=backup.recognitionReceipt;commitBackup(next,'Respaldo fusionado con tus datos.')}
function confirmBackupReplace(backup){const current=total(),importedTotal=backup.sessions.reduce((n,s)=>n+s.count,0);modal(`<h2>Reemplazar tus datos.</h2><p>Se sustituirán tus ${fmt(current)} daimoku actuales por ${fmt(importedTotal)} daimoku del respaldo.${current?' Antes se descargará una copia de seguridad.':''}</p><button class="primary" id="confirm-import-replace">Reemplazar mis datos</button><button class="text-button" id="cancel-import-replace">Cancelar</button>`);$('#cancel-import-replace').onclick=()=>$('#modal').close();$('#confirm-import-replace').onclick=()=>{if(current)downloadFile(JSON.stringify({app:'Daimoku Chile',schemaVersion:1,exportedAt:new Date().toISOString(),...data},null,2),'application/json',`respaldo-antes-de-importar-${localDay(Date.now())}.json`);const next={sessions:backup.sessions,intentions:backup.intentions,journeys:backup.journeys,rate:backup.rate,threshold:backup.threshold};if(backup.profile)next.profile=backup.profile;if(backup.recognitionReceipt)next.recognitionReceipt=backup.recognitionReceipt;commitBackup(next,'Respaldo importado. Tus datos fueron reemplazados.')}}
function commitBackup(next,message){try{localStorage.setItem(KEY,JSON.stringify(next))}catch{return toast('No se pudo guardar el respaldo. Revisa el espacio disponible en el navegador.')}data=next;render();$('#modal').close();toast(message)}
function initBackupImport(){const input=$('#import-file'),button=$('#import-backup');if(!input||!button)return;button.onclick=openBackupImport;input.onchange=()=>{const file=input.files&&input.files[0];input.value='';readBackupFile(file)}}
